<a class="back-link" href="<?= e(url('catalog',['module'=>$m->module])) ?>">← Volver a <?= e(mb_strtolower($m->meta['title'])) ?></a><section class="panel form-panel"><h2>Información del <?= e($m->meta['singular']) ?></h2><p class="text-secondary">Los campos marcados con * son obligatorios.</p><?php if($errors): ?><div class="alert alert-danger" role="alert"><strong>Revisa los datos antes de continuar.</strong><ul class="mb-0"><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach ?></ul></div><?php endif ?>
<form method="post" action="<?= e(url('catalog-save',['module'=>$m->module]+($id!==null?['id'=>$id]:[]))) ?>"><?= csrf_field() ?><div class="row g-4"><?php foreach($m->meta['fields'] as $col=>$f): $value=$row[$col]??''; ?><div class="<?= $f['type']==='textarea'?'col-12':'col-md-6' ?>"><label class="form-label" for="<?= e($col) ?>"><?= e($f['label']) ?><?= ($f['required']??false)?' *':'' ?></label>
<?php if($f['type']==='select'): ?><select id="<?= e($col) ?>" name="<?= e($col) ?>" class="form-select"><option value="">Sin asignar</option><?php foreach($options[$col] as $o): ?><option value="<?= e($o['id']) ?>" <?= (string)$value===(string)$o['id']?'selected':'' ?>><?= e($o['label']) ?></option><?php endforeach ?></select>
<?php elseif($f['type']==='textarea'): ?><textarea class="form-control" id="<?= e($col) ?>" name="<?= e($col) ?>" rows="3" maxlength="<?= e($f['max']) ?>"><?= e($value) ?></textarea>
<?php elseif($f['type']==='checkbox'): ?><div class="form-check form-switch"><input type="checkbox" class="form-check-input" id="<?= e($col) ?>" name="<?= e($col) ?>" value="1" <?= (int)$value?'checked':'' ?>><label class="form-check-label" for="<?= e($col) ?>">Sí, producto descontinuado</label></div>
<?php else: ?><input class="form-control <?= isset($errors[$col])?'is-invalid':'' ?>" type="<?= e($f['type']) ?>" id="<?= e($col) ?>" name="<?= e($col) ?>" value="<?= e($value) ?>" <?= ($f['required']??false)?'required':'' ?> <?= $col===$m->meta['pk'] && $id!==null?'readonly':'' ?> <?= $f['type']==='number'?'min="0" max="'.e($f['max']).'" step="'.(($f['decimal']??false)?'0.0001':'1').'"':'maxlength="'.e($f['max']).'"' ?>><?php endif ?></div><?php endforeach ?></div><div class="form-actions"><button class="btn btn-primary">Guardar <?= e($m->meta['singular']) ?></button><a class="btn btn-light" href="<?= e(url('catalog',['module'=>$m->module])) ?>">Cancelar</a></div></form></section>
